const PROCESSING_FEE = 5;
const FIRST_INSURANCE_RATE = 0.1;

const BASE_PREMIUM: Record<string, number> = {
  sword: 100,
  amulet: 60,
  staff: 80,
  potion: 40,
};

const COMPONENT_PREMIUM = 25;
const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
const BLOCK_SIZE = 3;
const BLOCK_PREMIUM = 60;

export interface Customer {
  yearsWithMHPCO: number;
}

export interface Item {
  type: string;
}

export interface QuoteStep {
  op: "quote";
  items: Item[];
}

export type Step = QuoteStep;

export interface Scenario {
  customer: Customer;
  steps: Step[];
}

export interface QuoteResult {
  premium: number;
}

export type StepResult = QuoteResult;

export interface ScenarioResult {
  results: StepResult[];
}

function itemBasePremium(item: Item): number {
  if (COMPONENT_TYPES.has(item.type)) {
    return COMPONENT_PREMIUM;
  }
  return BASE_PREMIUM[item.type];
}

function quotePremium(step: QuoteStep): number {
  const base = step.items.reduce((sum, item) => sum + itemBasePremium(item), 0);
  const firstInsurance = base * FIRST_INSURANCE_RATE;
  return Math.ceil(base + firstInsurance + PROCESSING_FEE);
}

export function runScenario(scenario: Scenario): ScenarioResult {
  const results = scenario.steps.map((step) => ({ premium: quotePremium(step) }));
  return { results };
}

