import { describe, it, expect } from "vitest";
import { runScenario } from "./claim-office.js";

describe("MHPCO Claim Office", () => {
  // --- Premium: base premiums and processing fee (simplest first) ---
  it("empty item list -> premium 5 G (only processing fee)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [] }],
    });
    expect(result.results).toEqual([{ premium: 5 }]);
  });
  it("single sword (no modifiers, newcomer's first) -> base 100 + 10 first insurance + 5 fee = 115 G", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "sword" }] }],
    });
    expect(result.results).toEqual([{ premium: 115 }]);
  });
  it("single amulet base premium 60 reflected in premium -> 71", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "amulet" }] }],
    });
    expect(result.results).toEqual([{ premium: 71 }]);
  });
  it("single staff base premium 80 reflected in premium -> 93", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "staff" }] }],
    });
    expect(result.results).toEqual([{ premium: 93 }]);
  });
  it("single potion base premium 40 reflected in premium -> 49", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "potion" }] }],
    });
    expect(result.results).toEqual([{ premium: 49 }]);
  });

  // --- Components and building blocks ---
  it("2 runes -> base 50 G (premium 60)", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "rune" }, { type: "rune" }] }],
    });
    expect(result.results).toEqual([{ premium: 60 }]);
  });
  it("3 runes -> base 60 G (block applies) -> premium 71", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        { op: "quote", items: [{ type: "rune" }, { type: "rune" }, { type: "rune" }] },
      ],
    });
    expect(result.results).toEqual([{ premium: 71 }]);
  });
  it("4 runes -> base 100 G (no block) -> premium 115", () => {
    const items = Array.from({ length: 4 }, () => ({ type: "rune" }));
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items }],
    });
    expect(result.results).toEqual([{ premium: 115 }]);
  });
  it("7 runes -> base 175 G -> premium 198 (197.5 rounded up)", () => {
    const items = Array.from({ length: 7 }, () => ({ type: "rune" }));
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items }],
    });
    expect(result.results).toEqual([{ premium: 198 }]);
  });
  it("2 runes + 1 moonstone -> base 75 G (no block: different types) -> premium 88", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [{ type: "rune" }, { type: "rune" }, { type: "moonstone" }],
        },
      ],
    });
    expect(result.results).toEqual([{ premium: 88 }]);
  });
  it("3 runes + 3 moonstones -> base 120 G (two separate blocks) -> premium 137", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [
        {
          op: "quote",
          items: [
            { type: "rune" },
            { type: "rune" },
            { type: "rune" },
            { type: "moonstone" },
            { type: "moonstone" },
            { type: "moonstone" },
          ],
        },
      ],
    });
    expect(result.results).toEqual([{ premium: 137 }]);
  });

  // --- Item-specific modifiers ---
  it("cursed sword adds 50% risk surcharge on that item's base premium -> 165", () => {
    const result = runScenario({
      customer: { yearsWithMHPCO: 0 },
      steps: [{ op: "quote", items: [{ type: "sword", cursed: true }] }],
    });
    expect(result.results).toEqual([{ premium: 165 }]);
  });
  it.todo("high enchantment (>=5) sword adds 30% surcharge; enchantment 5 is the threshold");
  it.todo("sword with enchantment 4 -> no high-enchantment surcharge");
  it.todo("cursed AND high-enchantment sword (enchantment 5) -> both surcharges apply");

  // --- Policy-wide modifiers ---
  it.todo("loyalty discount 20% applies at exactly 2 years with MHPCO");
  it.todo("less than 2 years -> no loyalty discount");
  it.todo("first insurance surcharge 10% applies on a quote");
  it.todo("follow-up contract 15% discount applies to each contract after the first quote in scenario");

  // --- Modifier scope on multi-item policies ---
  it.todo("cursed sword (100) + plain amulet (60) -> policy base 160, curse adds 50 -> 210 before policy modifiers + fee");

  // --- Rounding in MHPCO's favor ---
  it.todo("premium yielding 197.5 G -> rounded up to 198 G");
  it.todo("payout yielding 350.5 G -> rounded down to 350 G");

  // --- Integration examples ---
  it.todo("newcomer with cursed sword (0 yrs, ench 3) -> premium 165 G");
  it.todo("long-standing customer's second contract (3 yrs, cursed sword ench 7) -> premium 160 G");

  // --- Claim processing: standard reimbursement ---
  it.todo("regular sword (steel, ench 3), damage 500 -> payout 400 (full minus 100 deductible)");
  it.todo("rune (value 250), damage 200 -> payout 100 (full minus deductible, no special clause)");

  // --- Claim: enchantment clause ---
  it.todo("steel sword ench 9, damage 1000 -> payout 400 (50% then deductible)");

  // --- Claim: dragon material clause ---
  it.todo("dragon-material sword ench 5, damage 800 -> payout 700 (full reimbursement then deductible)");

  // --- Claim: both clauses (enchantment wins) ---
  it.todo("dragon-material sword ench 9, damage 1000 -> payout 400 (50% wins then deductible)");
  it.todo("dragon-material sword ench 8, damage 1000 -> payout 400 (high-enchantment applies then deductible)");

  // --- Claim: deductible per damage event ---
  it.todo("dragon attack damages sword (500) and amulet (300) -> payout 600 (deductible once per item)");

  // --- Claim: cap ---
  it.todo("sword+amulet -> insurance sum 1600, cap 3200");
  it.todo("cursed sword -> cap 2000 based on unmodified insurance value");
  it.todo("sword + 3 runes block -> insurance sum 1750 (block discount does not affect insurance sum)");
  it.todo("sword insured, two successive 1500 claims -> payout 1400 then 600, remainingCap 600 then 0");

  // --- Multiple items of same type ---
  it.todo("two swords -> insurance sum 2000, cap 4000; both damaged -> two separate deductibles");
  it.todo("more damage entries of a type than insured (two sword damages, one sword) -> non-zero exit / rejected");

  // --- Edge / error cases ---
  it.todo("quote with unknown item type (broomstick) -> non-zero exit, error to stderr, no results to stdout");
  it.todo("claim references item not in policy (amulet damaged, only sword insured) -> non-zero exit, error to stderr");
  it.todo("claim with negative damage amount (-200) -> non-zero exit, error to stderr");

  // --- CLI integration ---
  it.todo("CLI reads JSON scenario from stdin, writes results JSON to stdout (schema example)");
});

